# Get all polymorph files
polymorph_files = glob.glob('polymorph_data/*_polymorphs.json')

all_polymorphs = []
for file_path in polymorph_files:
    try:
        with open(file_path, 'r') as f:
            file_data = json.load(f)
            composition = os.path.basename(file_path).replace('_polymorphs.json', '')
            for polymorph in file_data:
                polymorph['source_composition'] = composition
            all_polymorphs.extend(file_data)
    except Exception as e:
        print(f'Error loading {file_path}: {e}')

filtered_data = all_polymorphs
print(f'Consolidated {len(filtered_data)} polymorphs from {len(polymorph_files)} files')
